def dx_extend(story_id,ids,coverage):
 s=next(s for s in stories if s['id']==story_id)
 s['transactions']=list(dict.fromkeys(s['transactions']+ids.split()))
 ev=[t for t in transactions if t['id'] in s['transactions']]
 s['transactions']=[t['id'] for t in sorted(ev,key=lambda t:(t['date'],t['order'],t['id']))]
 s['cutoff']=max(t['date'] for t in ev);s['endYear']=int(s['cutoff'][:4]);s['coverage']=coverage

dx_extend('luka','reddish-new-york davis-lakers mccollum-new-orleans hart-new-york kris-murray-draft mccollum-washington','Traces Luka, Trae and the Dallas first through Reddish; the Reddish–Hart exchange joins the 2019 Davis branch. Follows New York’s first to Kris Murray and McCollum into Washington’s 2026 Trae exchange. Stops February 5, 2026. Other pick rights and secondary player branches are untraced.')
dx_extend('dirk','shaq-miami shaq-phoenix marion-toronto shaq-cleveland marion-dallas','Follows the separate Dirk and Nash draft-night packages, Dallas’s 1999 first to Marion, and Marion through Miami and Toronto back to Dallas in July 2009. Shaq’s Miami, Phoenix and Cleveland exchanges are shared intersections. Conditional Toronto picks and other branches stop at their recorded transfers; Nash’s free agency is not a trade return.')
dx_extend('shaq','farmar-draft pinnock-lakers seibutis-draft shaq-phoenix marion-toronto shaq-cleveland marion-dallas caron-dallas vasquez-draft vasquez-new-orleans vasquez-sacramento vasquez-toronto vasquez-milwaukee anunoby-draft anunoby-knicks mogbo-draft','Follows both Shaq pick returns, Marion’s Dallas route, Butler’s Dallas exchange, the Gasol packages, and the Lakers 2010 first through Vásquez to Powell rights, Anunoby and Mogbo. Stops June 27, 2024. Untraced obligations are labelled; no free agency or shared championship is treated as a trade connection.')
dx_extend('gasol','vasquez-draft vasquez-new-orleans vasquez-sacramento vasquez-toronto vasquez-milwaukee anunoby-draft anunoby-knicks mogbo-draft','Follows Marc to Toronto and the Lakers 2010 first to Vásquez, then his New Orleans, Sacramento, Toronto and Milwaukee exchanges. The Clippers first becomes Anunoby; the later Knicks package’s Detroit second becomes Mogbo. Stops June 27, 2024. The Lakers 2008 first and other side branches remain untraced.')
dx_extend('davis','mccollum-new-orleans reddish-new-york hart-new-york kris-murray-draft mccollum-washington trae-wizards','The Davis route from 2019 through February 2026, plus Hart into the Reddish exchange and New York’s first into Kris Murray. McCollum’s New Orleans–Washington–Atlanta path is included, as is Chicago’s second through Washington to Dallas. Other rights are untraced beyond their displayed transactions.')
